    "pageParamMinimum": 1,
    "pageSizeParam": "per_page",
    "defaultPageSize": 10,
    "maxPageSize": 100,
    "maxPageSizeEnforcement": "server-side — a request above 100 is REJECTED, not silently clamped",
    "offsetParam": "offset",
    "offsetParamNote": "An `offset` param also exists on most collections and, where present, OVERRIDES page arithmetic.",
    "totalCountHeader": "X-WP-Total",
